const currentFeedbackId =
  $('Extract AI Analysis').first().json.feedback_id;

const history = $input.all();

const priorNegativeCount = history.filter(item => {
  const row = item.json;

  return (
    row.feedback_id !== currentFeedbackId &&
    Number(row.sentiment_score) < 0
  );
}).length;

return [
  {
    json: {
      ...$('Extract AI Analysis').first().json,
      prior_negative_count: priorNegativeCount
    }
  }
];

