const context=$('Prepare Feedback Context').first().json;
const raw=$input.first().json.text;
let analysis;
try { analysis=JSON.parse(String(raw??'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')); } catch { throw new Error('AI output is not valid JSON'); }
if(!analysis || Array.isArray(analysis) || !['Positive','Neutral','Negative'].includes(analysis.sentiment_label)) throw new Error('Invalid AI sentiment label');
for(const [key,min,max] of [['sentiment_score',-1,1],['severity_score',0,1],['confidence',0,1]]){
 if(typeof analysis[key]!=='number' || !Number.isFinite(analysis[key]) || analysis[key]<min || analysis[key]>max) throw new Error('Invalid AI score: '+key);
}
if(typeof analysis.summary!=='string' || !analysis.summary.trim()) throw new Error('Missing AI summary');
return [{json:{...context,sentiment_label:analysis.sentiment_label,sentiment_score:analysis.sentiment_score,severity_score:analysis.severity_score,confidence:analysis.confidence,summary:analysis.summary.trim()}}];

const current=$('Extract AI Analysis1').first().json;
const cutoff=Date.parse(current.received_at);
if(!Number.isFinite(cutoff)) throw new Error('Current feedback timestamp is invalid');
const ids=new Set();
for(const {json:row} of $input.all()){
 const at=Date.parse(row.received_at);
 if(row.customer_id===current.customer_id && row.feedback_id && row.feedback_id!==current.feedback_id && Number.isFinite(at) && at<cutoff && row.sentiment_score!=='' && Number.isFinite(Number(row.sentiment_score)) && Number(row.sentiment_score)<0) ids.add(row.feedback_id);
}
return [{json:{...current,prior_negative_count:ids.size}}];

